function dedupe(arr) {
  if (!Array.isArray(arr)) {
    return [];
  }
  const seen = new Set();
  const result = [];
  for (let i = 0; i < arr.length; i++) {
    const item = arr[i];
    if (item === null || typeof item !== 'object' || Array.isArray(item)) {
      result.push(item);
      continue;
    }
    const keys = Object.keys(item).sort();
    const normalized = {};
    for (let j = 0; j < keys.length; j++) {
      normalized[keys[j]] = item[keys[j]];
    }
    const key = JSON.stringify(normalized);
    if (!seen.has(key)) {
      seen.add(key);
      result.push(item);
    }
  }
  return result;
}

