 * 并且是时钟的唯一所有者。
 */

/**
 * 重试策略配置。
 */
export const DEFAULT_RETRY_POLICY = {
  /** 允许的最大尝试次数（含首次）。`1` 表示不重试——即使 `retryable: true` 的失败也会立即进入死信队列。 */
  maxAttempts: 5,
  /** 第二次尝试前的延迟（即第一次尝试失败后）。 */
  baseDelayMs: 60_000,
  /** 计算出的延迟上限，无论 `attempt` 增长到多高。 */
  maxDelayMs: 3_600_000,
};

/**
 * 验证策略配置的有效性。
 * @param {Object} policy - 重试策略对象。
 * @throws {RangeError} 如果配置无效。
 */
function assertValidPolicy(policy) {
  if (!Number.isInteger(policy.maxAttempts) || policy.maxAttempts < 1) {
    throw new RangeError(
      `retry.ts: maxAttempts 必须是正整数，得到 ${String(policy.maxAttempts)}`,
    );
  }
  if (!Number.isFinite(policy.baseDelayMs) || policy.baseDelayMs < 0) {
    throw new RangeError(
      `retry.ts: baseDelayMs 必须 >= 0，得到 ${String(policy.baseDelayMs)}`,
    );
  }
  if (!Number.isFinite(policy.maxDelayMs) || policy.maxDelayMs < policy.baseDelayMs) {
    throw new RangeError(
      `retry.ts: maxDelayMs (${String(policy.maxDelayMs)}) 必须 >= baseDelayMs (${String(policy.baseDelayMs)})`,
    );
  }
}

/**
 * 判断重试是否已耗尽。
 * @param {Object} policy - 重试策略对象。
 * @param {number} attempt - 当前尝试次数（1-indexed）。
 * @returns {boolean} 如果已耗尽则返回 true。
 */
export function isRetryExhausted(policy, attempt) {
  assertValidPolicy(policy);
  return attempt >= policy.maxAttempts;
}

/**
 * 计算下一次尝试前的延迟毫秒数。
 * 公式：baseDelayMs * 2^(attempt-1)，并受 maxDelayMs 限制。
 * @param {Object} policy - 重试策略对象。
 * @param {number} attempt - 刚刚失败的尝试次数（1-indexed）。
 * @returns {number} 下一次尝试前的延迟毫秒数。
 */
export function nextAttemptDelayMs(policy, attempt) {
  assertValidPolicy(policy);
  if (!Number.isInteger(attempt) || attempt < 1) {
    throw new RangeError(
      `retry.ts: attempt 必须是正整数，得到 ${String(attempt)}`,
    );
  }

  // 计算指数退避延迟
  // 使用 Math.min 确保即使指数溢出为 Infinity，结果也会被 maxDelayMs 限制
  const scaled = policy.baseDelayMs * Math.pow(2, attempt - 1);

  // 如果 scaled 是 Infinity，Math.min 会返回 maxDelayMs
  // 如果 baseDelayMs 是 0，scaled 是 0，Math.min 返回 0
  return Math.min(scaled, policy.maxDelayMs);
